function mapHTML(id,items,title='訪問順のマップ',sub='予定と同じ番号で、会場を表示',route=true){const known=items.filter(x=>geo(x.venue)),unknown=items.filter(x=>!geo(x.venue));return `<section class="map-panel" id="${id}" data-map-panel="${id}" aria-label="${esc(title)}"><div class="map-heading"><div><h2>${title}</h2><p>${sub}</p></div><div class="map-display-select" role="group" aria-label="地図の背景"><button data-map-mode="diagram" data-map="${id}" aria-pressed="true">位置図</button><button data-map-mode="road" data-map="${id}" aria-pressed="false">道路地図 ↗</button></div></div><div class="geo-map" tabindex="0" role="group" aria-label="会場地図。上下左右キーで移動、プラス・マイナスで拡大縮小。"><div class="map-tiles"></div><svg class="map-lines" aria-hidden="true"></svg><div class="map-markers"></div><span class="map-north">N<b>↑</b></span><div class="map-controls"><button data-map-zoom="1" data-map="${id}" aria-label="地図を拡大">＋</button><button data-map-zoom="-1" data-map="${id}" aria-label="地図を縮小">−</button><button data-map-fit="${id}" aria-label="全会場を地図に収める">全体</button></div><div class="map-scale"></div><span class="map-attribution">会場位置：掲載データ</span></div><div class="map-status">${known.length?'会場座標による位置図。':'表示できる会場座標がありません。'}${route?'破線は訪問順で、実際の歩行経路ではありません。':'実際の道順は経路リンクで確認してください。'}</div>${unknown.length?`<div class="map-unknown">位置未確認 ${unknown.length}件：${unknown.map(x=>esc(x.venue?.name||'会場未確認')).join('、')}。地図上の訪問順には含めていません。</div>`:''}<div class="map-legend"><span><i></i>訪問先</span><span><i class="gf"></i>Garraway F</span><span>番号をタップして詳細（？は順序未定）</span></div><div class="map-selected" hidden></div>${route?`<div class="map-route-list">${items.map(x=>`<button class="map-route-row" data-map-item="${esc(x.key)}" data-map="${id}"><span class="stop-number">${x.number}</span><span>${esc(x.venue?.name||'会場要確認')}</span><small>${time(x.start)}</small></button>`).join('')}</div>`:''}</section>`;}
