 const title=leg?`${leg.from.venue?.name||'会場'} → ${leg.to.venue?.name||'会場'}`:e?.title||entry?.title||'移動区間';
 let action=`data-focus-plan="${esc(x.key)}"`,label='この予定を確認する';
 if(x.type==='move'){action=`data-edit-leg="${esc(x.key)}"`;label='移動時間を確認する';}
