function renderAllMap(){$('#map-scope').value=mapScope;$('#map-area').innerHTML='<option value="all">すべて</option>'+[...new Set(D.venues.map(v=>v.area))].sort().map(a=>`<option value="${esc(a)}">${esc(a)}</option>`).join('');$('#map-area').value=mapArea;const vs=visibleVenues(),items=mapScope==='plan'?planItems(itinerary(model.day)).filter(x=>vs.some(v=>v.id===x.venue?.id)):vs.map((v,i)=>({key:'venue-'+v.id,venue:v,number:i+1,title:v.name,start:null}));$('#allmap-content').innerHTML=`<div class="allmap-layout"><div>${mapHTML('all-map',items,mapScope==='plan'?dayName(model.day)+'のマイ予定':'会場マップ',`${vs.length}会場 ／ 位置確認済み ${vs.filter(v=>geo(v)).length}会場`,mapScope==='plan')}</div><div class="venue-list">${vs.map(v=>`<article class="venue-row"><span class="badge ${geo(v)?'blue':'warn'}">${geo(v)?esc(v.area):'位置未確認'}</span><h3>${esc(v.name)}</h3><p>${esc(v.geo?.address||v.note||'詳しい場所・利用条件は主催者案内で確認してください。')}</p><div class="venue-actions"><button data-search-venue="${esc(v.id)}">この会場の予定を見る</button>${link(placeLink(v),'地図で確認 ↗')}</div></article>`).join('')||'<div class="empty-state"><h3>対象の会場がありません</h3><p>日付や表示条件を変更してください。</p></div>'}</div></div>`;mountMap('all-map',items,mapScope==='plan');}
function renderGF(){const own=D.events.filter(e=>e.venue==='garraway'&&e.origin==='主催者予定');$('#gf-events').innerHTML=[7,8,9].map(n=>{const day='2026-10-0'+n;return `<h2 class="gf-day-title">${dayName(day)}</h2>`+own.filter(e=>e.dates.includes(day)).sort((a,b)=>(slot(a,day)[0]||'').localeCompare(slot(b,day)[0]||'')).map(e=>cardHTML(e,day)).join('');}).join('');$('[data-gf-map]').href=placeLink(VEN.get('garraway'));}
function openModal(type,title,html){modalType=type;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;const dlg=$('#modal');if(!dlg.open)dlg.showModal();$('#modal-body').scrollTop=0;requestAnimationFrame(()=>dlg.querySelector('.close-dialog')?.focus({preventScroll:true}));}
function closeModal(){if($('#modal').open)$('#modal').close();modalType='';}
function selectedOption(value,current){return String(value)===String(current)?' selected':'';}
function options(values,current){return values.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}"${selectedOption(v,current)}>${esc(t)}</option>`;}).join('');}
function openFilters(){openModal('filters','イベントを絞り込む',`<p class="modal-intro">条件を選んで、必要なイベントだけに。無料でも申込が必要な場合があります。</p><form id="filter-form"><div class="field-grid"><label class="field"><span>会場</span><select name="venue">${options([['all','すべての会場'],...D.venues.map(v=>[v.id,v.name])],filters.venue)}</select></label><label class="field"><span>テーマ</span><select name="category">${options([['all','すべてのテーマ'],...[...new Set(D.events.map(e=>e.category))].sort()],filters.category)}</select></label><label class="field"><span>エリア</span><select name="area">${options([['all','すべてのエリア'],...[...new Set(D.venues.map(v=>v.area))].sort()],filters.area)}</select></label><label class="field"><span>時間帯（重なる予定も表示）</span><select name="period">${options([['all','すべて'],['morning','午前（12時まで）'],['afternoon','午後（12〜18時）'],['evening','夕方から（18時以降）'],['unknown','時刻未確定']],filters.period)}</select></label><label class="field"><span>参加費・申込条件</span><select name="fee">${options([['all','すべて'],['free','無料と明記'],['no-registration','無料・予約不要と明記']],filters.fee)}</select></label><label class="field"><span>イベントとセッション</span><select name="kind">${options([['grouped','関係をまとめて表示'],['events','イベント全体だけ'],['sessions','個別セッションだけ'],['all','すべて独立して表示']],filters.kind)}</select></label><label class="field"><span>この時刻以降に開始</span><input name="from" type="time" value="${esc(filters.from)}"></label><label class="field"><span>この時刻までに終了</span><input name="until" type="time" value="${esc(filters.until)}"></label></div><p class="file-help">時刻指定は、その時間内に全体が収まる予定を表示します。未公表・不一致の時刻は除外します。</p><label class="check-field"><input type="checkbox" name="known" ${filters.known?'checked':''}>時刻が確認できる予定だけ</label><label class="check-field"><input type="checkbox" name="candidates" ${filters.candidates?'checked':''}>♡ 気になるに保存したものだけ</label><div id="form-error" class="form-error" hidden role="alert"></div><div class="form-actions"><button type="button" class="button secondary" data-action="reset-filters-modal">条件を解除</button><button type="submit" class="button primary">この条件で表示</button></div></form>`);}
function detail(id,day){const e=EV.get(id);if(!e)return;if(!e.dates.includes(day))day=e.dates[0];pending={type:'detail',id,day};const [a,b]=slot(e,day),v=VEN.get(e.venue),x=model.entries[k(id,day)],saved=model.candidates.includes(id),safe=knownTime(e,day)&&(!['check','soldout'].includes(e.status)||x?.reviewed===signature(e,day)),sourceDate=e.autoCheckedAt||e.checkedAt||D.meta.fetchedAt;const parent=e.parent&&EV.get(e.parent),cs=(children.get(id)||[]).filter(c=>c.dates.includes(day));
 openModal('detail','イベントの詳細',`<div class="badges">${e.category?'<span class="badge blue">'+esc(e.category)+'</span>':''}${statusBadges(e,day)}</div><h3 class="detail-title">${esc(e.title)}</h3>${e.dates.length>1?`<label class="field"><span>参加する日を選ぶ</span><select id="detail-date" data-id="${esc(id)}">${options(e.dates.map(d=>[d,dayName(d)]),day)}</select></label>`:`<p class="event-date">${dayName(day)}</p>`}<p class="detail-clock">${esc(a||'時刻未公表')}${b?'–'+esc(b):''}</p><p class="detail-place">${esc(v?.name||'会場要確認')}</p><p class="subtle">${esc(e.room||'')} ${v?.geo?.address?'<br>'+esc(v.geo.address):''}</p><div class="badges">${feeBadge(e)}<span class="badge">${isFlexible(e)?'入退場自由の記載あり':'途中入退場は要確認'}</span></div>${e.speaker?`<p class="detail-description"><b>登壇者</b><br>${esc(e.speaker)}</p>`:''}${e.description?`<p class="detail-description">${esc(e.description)}</p>`:''}<div class="detail-notes">${(e.notes||[]).map(n=>'<p>'+esc(n)+'</p>').join('')}</div>${parent?`<p class="manual-note">このセッションは「${esc(parent.title)}」の一部です。<button class="text-button" data-detail="${esc(parent.id)}" data-day="${day}">イベント全体を見る</button></p>`:''}${cs.length?'<div class="help-section"><h3>この日の個別セッション</h3>'+cs.map(c=>`<button class="text-button" style="display:block;text-align:left" data-detail="${esc(c.id)}" data-day="${day}">${esc(slot(c,day).filter(Boolean).join('–'))} ${esc(c.title)} ↗</button>`).join('')+'</div>':''}<div class="detail-actions"><button class="button secondary" data-candidate="${esc(id)}" aria-pressed="${saved}">${saved?'♥ 気になるに保存済み':'♡ 気になるに保存'}</button><button class="button primary" data-add="${esc(id)}" data-day="${day}" aria-pressed="${!!x}">${x?'✓ 行く予定に追加済み':'＋ 行く予定に入れる'}</button></div><p class="file-help">「気になる」とマイ予定は別です。どちらも参加予約ではありません。この端末・ブラウザに保存されます。</p><div class="detail-actions">${url(e.url)?link(e.url,'主催者サイトで申し込む ↗','button dark'):'<span class="manual-note">Garraway F独自企画。参加条件は上記の主催者予定をご確認ください。</span>'}${link(placeLink(v),'会場・経路 ↗','button secondary')}</div>${x?`<button class="button secondary" data-registration="${esc(k(id,day))}">${regLabel({x,e})} → 記録</button>`:''}<div class="detail-actions"><button class="button secondary" data-google-event="${esc(id)}" data-day="${day}" ${safe?'':'disabled'}>Googleカレンダーへ ↗</button><button class="button secondary" data-ics-event="${esc(id)}" data-day="${day}" ${safe?'':'disabled'}>この枠を .ics 保存</button></div>${!safe?'<p class="file-help">時刻が未確定・不一致、または開催条件が要確認です。マイ予定に保存して内容を確認してから書き出してください。中止・未確定時刻は書き出せません。</p>':''}<div class="detail-source"><b>掲載情報の出典</b><br>${url(e.source)?link(e.source,esc(e.source)):esc(e.source||e.origin||'掲載データ')}<br>確認時点：${esc(sourceDate)}<br>主催者による更新がこの保存データに反映されていない場合があります。出発前に最新の主催者案内を確認してください。</div>`);
}
function findLeg(key){for(const day of daysInPlan()){const l=itinerary(day).legs.find(l=>l.key===key);if(l)return l;}return null;}
function editLeg(key){const l=findLeg(key);if(!l){toast('移動区間が変わりました。最新の予定表をご確認ください。');return;}pending={type:'leg',key};openModal('leg','移動方法・所要時間を変更',`<p class="modal-intro"><strong>${esc(l.from.venue?.name||'会場未確認')}</strong><br>↓<br><strong>${esc(l.to.venue?.name||'会場未確認')}</strong></p><form id="leg-form" data-key="${esc(key)}"><label class="field"><span>移動方法</span><select name="mode" id="leg-mode">${options([['walking','徒歩'],['transit','公共交通'],['driving','車・タクシー']],l.mode)}</select></label><label class="field"><span>確認した所要時間（分）</span><input name="minutes" id="leg-minutes" type="number" inputmode="numeric" min="0" max="720" step="1" value="${l.manual?l.minutes:''}" placeholder="地図で確認した分数を入力"><small>徒歩は空欄で目安を自動計算。公共交通と車・タクシーは入力が必要です。</small></label>${link(l.url,'Googleマップで経路・時間を確認 ↗','button secondary')}<p class="file-help">地図側で利用日・出発時刻を設定し、待ち時間・乗り換えも含めて入力してください。予備時間${model.settings.buffer}分は別に加算します。</p><div class="notice">現在の算定：${esc(l.method)}${l.minutes!==null?' ／ '+l.minutes+'分':''}<br>同じ会場は移動0分。別会場の徒歩目安は直線距離×1.35を歩行速度で割り、5分単位に切り上げます。</div><div id="form-error" class="form-error" hidden role="alert"></div><div class="form-actions"><button type="button" class="button secondary" data-action="reset-leg">徒歩の自動計算に戻す</button><button type="submit" class="button primary">この移動に反映</button></div></form>`);}
function editTime(key){const r=dayRows(model.entries[key]?.day).find(r=>r.key===key);if(!r||!r.e||!knownTime(r.e,r.day)){toast('公表時刻が未確定のため、参加時間を調整できません。');return;}pending={type:'time',key};openModal('time','自分が参加する時間を調整',`<p class="modal-intro"><strong>${esc(r.e.title)}</strong><br>${dayName(r.day)} ／ 開催時間 ${esc(r.sourceStart)}–${esc(r.sourceEnd)}</p><form id="visit-form" data-key="${esc(key)}"><div class="field-grid"><label class="field"><span>参加開始</span><input type="time" name="start" value="${esc(r.x.start||r.sourceStart)}" required></label><label class="field"><span>参加終了</span><input type="time" name="end" value="${esc(r.x.end||r.sourceEnd)}" required></label></div>${isFlexible(r.e)?'<div class="notice">主催者予定に「入退場自由」の記載があります。</div>':'<label class="check-field"><input type="checkbox" name="partial" '+(r.x.partialConfirmed?'checked':'')+'>主催者案内で途中入退場が可能と確認した</label><p class="file-help">時間を変更できることと、途中入退場できることは別です。講演・セッションを途中で切る場合は確認が必要です。</p>'}<div id="form-error" class="form-error" hidden role="alert"></div><div class="form-actions"><button type="button" class="button secondary" data-reset-time="${esc(key)}">開催時間に戻す</button><button type="submit" class="button primary">参加時間を反映</button></div></form>`);}
function registration(key){const x=model.entries[key],e=EV.get(x?.id);if(!x)return;pending={type:'registration',key};openModal('registration','申込状況を記録する',`<p class="modal-intro"><strong>${esc(e?.title||x.title)}</strong><br>${dayName(x.day)}<br>これは自分用の記録です。主催者への申し込みは行われません。</p>${url(e?.url)?link(e.url,'主催者サイトで申し込む ↗','button dark'):''}<form id="registration-form" data-key="${esc(key)}" style="margin-top:20px"><label class="field"><span>現在の状態（自己申告）</span><select name="registration">${options([['unknown','まだ確認していない'],['pending','申込が必要・まだ申し込んでいない'],['done','申し込みを完了した'],['notrequired','申込不要と確認した']],x.registration)}</select></label><p class="file-help">申込ページを開いただけでは「申込済み」になりません。完了メールなどをご自身で確認して記録してください。</p><div class="form-actions"><button class="button primary" type="submit">この日の記録を保存</button></div></form>`);}
function review(key){const x=model.entries[key],e=EV.get(x?.id);if(!x||!e){toast('現在のデータに予定がありません。主催者の案内をご確認ください。');return;}const r=dayRows(x.day).find(r=>r.key===key);let old=null;try{old=JSON.parse(x.snapshot);}catch{}pending={type:'review',key};openModal('review','開催情報と変更内容を確認',`<h3>${esc(e.title)}</h3>${r.changed?`<div class="review-change"><div><small>保存したとき</small>${esc(old?.[0]||x.title)}<br>${esc(old?.[3]||x.day)} ${esc(old?.[4]||'未確認')}–${esc(old?.[5]||'未確認')}<br>${esc(VEN.get(old?.[1])?.name||x.venue)}<br>${esc(old?.[8]||'')}</div><div><small>今回の掲載データ</small>${esc(e.title)}<br>${esc(x.day)} ${esc(slot(e,x.day)[0]||'未確認')}–${esc(slot(e,x.day)[1]||'未確認')}<br>${esc(VEN.get(e.venue)?.name)}<br>${esc(e.fee||'')}</div></div>`:''}<div class="detail-notes">${(e.notes||[]).map(n=>'<p>'+esc(n)+'</p>').join('')}</div>${e.status==='soldout'?'<div class="notice warn">完売表記があります。参加可否を主催者に確認してください。</div>':''}${link(e.url||url(e.source),'主催者の最新案内を確認 ↗','button dark')}<p class="file-help">この画面は${esc(D.meta.fetchedAt||D.meta.checkedAt)}時点の保存データです。未確定の時刻・中止の予定は、確認を記録しても書き出せません。</p><form id="review-form" data-key="${esc(key)}"><label class="check-field"><input type="checkbox" name="read" required>変更内容・主催者の開催条件を確認しました</label><div class="form-actions">${knownTime(e,x.day)&&r.invalid?`<button type="button" class="button secondary" data-reset-time="${esc(key)}">参加時間を公表時間に戻す</button>`:''}<button type="submit" class="button primary">確認したことを記録</button></div></form>`);}
function openSettings(){openModal('settings','移動と保存の設定',`<form id="settings-form"><div class="field-grid"><label class="field"><span>会場到着後の予備時間</span><select name="buffer">${options([0,5,10,15,20,30].map(x=>[x,x+'分']),model.settings.buffer)}</select></label><label class="field"><span>徒歩の計算速度</span><select name="speed">${options([[50,'ゆっくり（50m/分）'],[70,'標準（70m/分）'],[90,'速め（90m/分）']],model.settings.speed)}</select></label></div><div class="notice">同じ会場は移動0分、別フロアなど同じ建物付近は目安5分。予備時間は別に加算します。徒歩は実際の道順、信号、階段、入口を考慮した経路計算ではありません。移動条件に合わせて区間ごとに調整してください。</div><div class="form-actions"><button type="submit" class="button primary">予定表に反映</button></div></form><div class="help-section"><h3>別の端末に予定を渡す</h3><p>このブラウザに保存します。アカウント登録や自動同期はありません。予定ファイルを書き出し、別端末で読み込むと移動設定も引き継げます。</p><div class="detail-actions"><button class="button secondary" data-action="backup">予定ファイルを書き出す</button><button class="button secondary" data-action="import">予定ファイルを読み込む</button></div></div><div class="help-section"><h3>旧版の保存データ</h3><p>同じブラウザ内の旧版データを、明示的に読み込めます。旧版のデータは削除・変更しません。候補から予定を自動生成することもありません。</p><button class="button secondary" data-action="import-legacy">旧版の保存を読み込む</button></div>`);}
function formError(text){const el=$('#form-error');if(el){el.textContent=text;el.hidden=false;el.scrollIntoView({block:'nearest'});}else toast(text);}
function suggestGap(key){const g=daysInPlan().flatMap(d=>itinerary(d).gaps).find(g=>g.key===key);if(!g){toast('予定が変わりました。最新の空き時間をご確認ください。');return;}let picks=[];for(const e of D.events){if(!e.dates.includes(g.from.day)||!knownTime(e,g.from.day)||['check','soldout','cancelled'].includes(e.status)||model.entries[k(e.id,g.from.day)]||relationEntries(e.id,g.from.day).length)continue;const v=VEN.get(e.venue),go=estimate(g.from.venue,v),back=estimate(v,g.to.venue);if(go.minutes===null||back.minutes===null)continue;const [a,b]=slot(e,g.from.day).map(min),start=Math.max(a,g.from.end+go.minutes+model.settings.buffer),end=Math.min(b,g.to.start-back.minutes-model.settings.buffer);if(end-start<20)continue;if(!isFlexible(e)&&(start!==a||end!==b))continue;if(start<g.start||end>g.end)continue;picks.push({e,start,end,go:go.minutes,back:back.minutes});}
 picks.sort((a,b)=>(a.go+a.back)-(b.go+b.back)||a.start-b.start);pending={type:'gap',day:g.from.day,picks:picks.slice(0,8)};openModal('gap','空き時間に立ち寄れる企画',`<p class="modal-intro">${dayName(g.from.day)} ${time(g.start)}–${time(g.end)} の空き時間。前後の会場への徒歩目安と予備時間を含めて、時間上収まる候補です。</p><div class="notice warn">満席・申込状況は確認していません。利用できることを保証するおすすめではありません。入退場自由と明記された企画だけ、部分参加を候補に含めます。</div>${picks.length?picks.slice(0,8).map((p,i)=>`<article class="recommend-card"><span class="badge blue">前後の移動 計${p.go+p.back}分の目安</span><h3>${esc(p.e.title)}</h3><p>${esc(VEN.get(p.e.venue)?.name)} ／ ${time(p.start)}–${time(p.end)} の参加<br>${esc(p.e.fee)}</p><button class="button primary" data-add-suggestion="${i}">この時間で予定に追加</button><button class="text-button" data-detail="${esc(p.e.id)}" data-day="${g.from.day}">参加条件を見る</button></article>`).join(''):empty('条件を満たす企画は見つかりませんでした。','この時間は休憩・食事のために空けておくか、検索で他の候補をご確認ください。','<button class="button secondary" data-action="close-modal">予定表に戻る</button>')}`);}
function openHelp(){openModal('help','使い方・データと保存について',`<div class="help-steps"><div class="help-step"><div><h3>参加する日から探す</h3><p>会場・テーマ・料金・時間帯で絞り込めます。複数の検索語はスペースで区切ります。英字の大小、全半角、ひらがな・カタカナは区別しません。</p></div></div><div class="help-step"><div><h3>♡は気になる。＋は、この日の予定。</h3><p>候補と参加予定は別々です。複数日イベントでも追加した日だけが予定になります。参加の申し込みは主催者案内から行ってください。</p></div></div><div class="help-step"><div><h3>地図と移動を見て一日を組む</h3><p>マイ予定と地図は同じ番号で対応します。同じ会場に戻る場合は「1・4」のように表示。移動と予備時間、空き時間も確認できます。</p></div></div><div class="help-step"><div><h3>保存して、当日は次の会場へ</h3><p>保存の対象を「この日／全日程」から選べます。当日ナビは選んだ予定を案内します。現在地を勝手に取得したり、申込を自動実行したりはしません。</p></div></div></div><div class="help-section"><h3>このガイドについて</h3><p>${CFG.preview?'公開前の独立したプレビューです。公開サイトと既存の保存済み予定は変更していません。操作例は別の保存領域を使い、実際の予約ではありません。':'Garraway Fが編集する非公式回遊ガイドです。'}</p><p>データ取得時点：${esc(D.meta.fetchedAt||D.meta.checkedAt)}。${D.events.filter(e=>e.kind==='event').length}イベント・${D.events.filter(e=>e.kind==='session').length}個別セッションを保存しています。複数日開催は日別の枠として表示します。</p><p>登録先と時間割で不一致・未公表の情報があります。公表されていないイベントもあり、完全網羅・リアルタイム更新を保証しません。このプレビューは保存データを使い、自動取得処理を実行しません。</p></div><div class="help-section"><h3>移動と地図の見方</h3><p>位置図は掲載会場の座標によるものです。実際の道路を描いたものではありません。破線は訪問順。入口・バリアフリー経路・信号・交通状況を考慮した経路ではありません。</p><p>徒歩目安は、直線距離×1.35÷歩行速度を5分単位で切り上げます。同じ会場0分、同じ建物付近5分、5kmを超える区間・位置未確認の会場は自動算定しません。</p><p>道路地図と外部経路には通信が必要です。ローカルHTMLでは道路地図を別タブで開きます。Web上ではOpenStreetMapの地図画像を利用でき、外部サービスへの通信が発生します。地図提供元の利用条件に従います。</p></div><div class="help-section"><h3>端末保存・カレンダー</h3><p>ログインなしでこのブラウザに保存します。別ブラウザ・別端末には自動同期されません。閲覧データを削除すると消えるため「予定ファイル」のバックアップをご利用ください。</p><p>プライベートブラウズやアプリ内ビューアでは保存・HTML操作・ダウンロードに制約がある場合があります。通常のブラウザでの確認を推奨します。</p><p>カレンダーファイルは一時点のコピーです。主催者の変更は自動同期されません。再取り込み時の重複処理はカレンダーアプリに依存します。主催者の最新案内を前日・当日に確認してください。</p></div><div class="help-section"><h3>出典</h3>${(D.meta.sources||[]).map(u=>'<p>'+link(u,esc(u))+'</p>').join('')}<p>Garraway F独自企画は主催者予定として区別しています。</p></div><div class="detail-actions"><button class="button primary" data-action="demo">操作例で試す</button><button class="button secondary" data-action="settings">保存の設定</button></div>`);}
// Calendar exports always state scope before writing. Unknown transfers block itinerary ICS, not backup/print/text.
function stamp(day,n){const d=new Date(day+'T00:00:00+09:00');d.setTime(d.getTime()+n*60000);return d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');}
const icsEscape=s=>String(s??'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');
function fold(s){let lines=[],part='',bytes=0;for(const c of s){const n=new TextEncoder().encode(c).length;if(bytes+n>73){lines.push(part);part=' ';bytes=1;}part+=c;bytes+=n;}lines.push(part);return lines.join('\r\n');}
function calendarRows(p){const out=p.ordered.map(r=>({uid:r.key,title:r.e.title,start:r.start,end:r.end,day:r.day,location:venueLocation(r.venue),description:'自分の参加予定。予約ではありません。主催者開催時間 '+r.sourceStart+'–'+r.sourceEnd+'。開催情報の変更は自動同期されません。',url:ROOT+'?date=any&event='+encodeURIComponent(r.e.id)+'&on='+r.day}));for(const l of p.legs){if(l.minutes!==null&&l.depart!==null&&l.minutes>0)out.push({uid:'move-'+l.key,title:`【${l.manual?'手入力':'目安'}】${l.from.venue?.name} → ${l.to.venue?.name}`,start:l.depart,end:l.arrive,day:p.day,location:venueLocation(l.to.venue),description:l.method+'。実際の経路・到着時刻を保証しません。',url:l.url});if(l.arrive!==null&&l.buffer>0)out.push({uid:'buffer-'+l.key,title:'【予備時間】'+l.to.venue?.name,start:l.arrive,end:l.arrive+l.buffer,day:p.day,location:venueLocation(l.to.venue),description:'移動後の入館・受付の予備時間。移動0分の同じ会場でも別途確保。',url:ROOT});}return out.sort((a,b)=>a.start-b.start);}
function createICS(rows){const now=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Garraway F//RAMEN Guide V3//JA','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const r of rows)lines.push('BEGIN:VEVENT','UID:'+icsEscape(r.uid)+'@ramen-guide.garrawayf.github.io','DTSTAMP:'+now,'DTSTART:'+stamp(r.day,r.start),'DTEND:'+stamp(r.day,r.end),'SUMMARY:'+icsEscape(r.title),'LOCATION:'+icsEscape(r.location),'DESCRIPTION:'+icsEscape(r.description),'URL:'+r.url,'STATUS:TENTATIVE','END:VEVENT');lines.push('END:VCALENDAR');return lines.map(fold).join('\r\n')+'\r\n';}
function download(name,content,mime){const blob=new Blob([content],{type:mime}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),15000);}
function exportDays(){return exportScope==='all'?daysInPlan():daysInPlan().includes(model.day)?[model.day]:[];}
function exportSummary(){const ds=exportDays(),ps=ds.map(itinerary),issues=ps.reduce((n,p)=>n+p.issues.length,0),events=ps.reduce((n,p)=>n+p.rows.length,0),legs=ps.reduce((n,p)=>n+p.legs.length,0);return {ds,ps,issues,events,legs};}
function openExport(){const days=daysInPlan();if(!days.length){toast('まずイベントをマイ予定に追加してください。');return;}if(!days.includes(model.day))model.day=days[0];openModal('export','予定を保存・共有',`<p class="modal-intro">保存する対象を明確にしてから書き出します。予定ファイルは、このブラウザと別の端末の間で受け渡しできます。</p><label class="field"><span>対象の日程</span><select id="export-scope">${options([['day',dayName(model.day)+'だけ'],['all','全日程（'+days.length+'日分）']],exportScope)}</select></label><div id="export-summary" class="export-summary"></div><div class="export-actions"><button class="button primary" data-action="export-ics">移動込みカレンダー .ics <span>↓</span></button><button class="button secondary" data-action="copy-plan">この範囲をテキスト共有 <span>↗</span></button><button class="button secondary" data-action="print-plan">この範囲の予定表を印刷 <span>↗</span></button><button class="button secondary" data-action="backup">全予定のバックアップ .json <span>↓</span></button></div><div id="export-error" class="notice warn" hidden></div><p class="file-help">.icsは自分の予定と移動のコピーです。参加予約・情報の自動同期ではありません。JSONは候補・全日程・申込メモ・移動設定を含むバックアップです。</p><div class="help-section"><h3>別端末へ引き継ぐ</h3><p>全予定のバックアップを別端末へ送り、この画面から読み込んでください。既存データの扱いを確認してから反映します。</p><button class="button secondary" data-action="import">予定ファイルを読み込む</button></div>`);updateExportSummary();}
function updateExportSummary(){
 const s=exportSummary();$('#export-summary').innerHTML=`<strong>${s.ds.map(d=>dayName(d)).join('・')}</strong><br>参加予定 ${s.events}件 ／ 移動 ${s.legs}区間${s.issues?`<div class="export-checks"><h3>保存前に、${s.issues}件確認してください</h3><ul class="issue-list">${s.ps.flatMap(p=>p.issues).map(issueAction).join('')}</ul></div>`:''}`;
 const b=$('[data-action="export-ics"]');if(b)b.textContent=(exportScope==='all'?'全日程':dayName(model.day))+'をカレンダー保存';
}
function exportICS(){const s=exportSummary();if(s.issues){const er=$('#export-error');if(er){er.hidden=false;er.innerHTML='上の確認項目から、該当する予定・移動を確認できます。テキスト・印刷・バックアップは注意事項付きで保存できます。';$('#export-summary').scrollIntoView({block:'start'});}toast('確認が必要な予定があります。該当箇所を直してから保存してください。');return false;}download('ramen-plan-'+(exportScope==='all'?'all-days':model.day)+'.ics',createICS(s.ps.flatMap(calendarRows)),'text/calendar;charset=utf-8');toast(s.ds.length+'日分のイベント・移動・予備時間を書き出しました。');return true;}
function shareText(days){const lines=['RAMEN TECH 2026 非公式回遊ガイド｜Garraway F','自分の参加予定（参加予約ではありません）'];if(demo)lines.push('【操作例】実在の企画を使った仮の参加計画です。');for(const day of days){const p=itinerary(day);lines.push('',dayName(day));if(p.issues.length)lines.push('【要確認】'+[...new Set(p.issues.map(x=>x.text))].join(' / '));for(let i=0;i<p.ordered.length;i++){const r=p.ordered[i];lines.push(`${r.number}. ${time(r.start)}–${time(r.end)} ${r.e.title}`,`   ${r.venue?.name||'会場確認'} ／ ${regLabel(r)}`);const l=p.legs[i];if(l){lines.push(`   移動 ${l.minutes===null?'未確認':l.minutes+'分'}（${l.method}）＋予備 ${l.buffer}分`);const g=p.gaps.find(g=>g.key===l.key);if(g)lines.push(`   空き ${time(g.start)}–${time(g.end)}（${g.minutes}分）`);}}for(const r of p.unresolved)lines.push('時刻・開催情報未確認：'+(r.e?.title||r.x.title));}lines.push('','移動は目安です。開催・申込条件と実際の経路は出発前に主催者・地図で確認してください。','掲載データ取得時点：'+D.meta.fetchedAt,ROOT);return lines.join('\n');}
async function copyPlan(){const text=shareText(exportDays());try{await navigator.clipboard.writeText(text);toast('選択した日程の予定をコピーしました。');}catch{openModal('copy','予定をコピー',`<p class="modal-intro">コピーできないブラウザでは、下の文章を選択してコピーするか、テキストファイルに保存してください。</p><textarea class="share-text" id="copy-text" readonly>${esc(text)}</textarea><div class="form-actions"><button class="button primary" data-action="download-text">テキストファイルを保存</button></div>`);$('#copy-text').focus();$('#copy-text').select();}}
function backup(){download('ramen-guide-backup-'+(demo?'sample-':'')+nowJST().day+'.json',JSON.stringify({...model,exportedAt:new Date().toISOString(),sample:demo,source:'RAMEN TECH guide v3'},null,2),'application/json;charset=utf-8');toast('候補・全日程・移動設定を予定ファイルに保存しました。');}
function importFile(){openModal('import','予定ファイルを読み込む',`<p class="modal-intro">このガイドで書き出した .json ファイルを選んでください。読み込み内容と、既存の予定の扱いを確認してから反映します。</p><label class="field"><span>バックアップファイル（最大2MB）</span><input id="import-file" type="file" accept="application/json,.json"></label><div id="form-error" class="form-error" hidden role="alert"></div>`);}
function importConfirm(m,sample=false){pending={type:'import',model:m};openModal('import-confirm','読み込み内容を確認',`<div class="export-summary">候補 ${m.candidates.length}件 ／ 参加予定 ${Object.keys(m.entries).length}件<br>${[...new Set(Object.values(m.entries).map(x=>x.day))].map(d=>dayName(d)).join('・')||'参加予定なし'}${sample?'<br><b>操作例として書き出されたデータです。</b>':''}</div><p class="modal-intro">追加の場合、同じ日・同じイベントが既にあれば、現在の予定を優先します。元のバックアップや旧版のデータは書き換えません。</p><div class="merge-choice"><button class="button primary" data-action="merge-import">今の予定に追加する（既存を優先）</button><button class="button secondary" data-action="replace-import-confirm">今の予定を置き換える…</button><button class="button secondary" data-action="close-modal">読み込まない</button></div>`);}
function importLegacy(){try{const raw=JSON.parse(localStorage.getItem('ramen-itinerary-v1')||'null'),oldCandidates=JSON.parse(localStorage.getItem('garrawayf-ramen-city-2026-favorites-v2')||'[]');if(!raw&&!oldCandidates?.length){toast('このブラウザには旧版の保存データがありません。別ドメイン・別端末の保存は読み込めません。');return;}const m=newModel();m.candidates=Array.isArray(oldCandidates)?oldCandidates.filter(x=>EV.has(x)):[];for(const [key,x] of Object.entries(raw?.entries||{})){const e=EV.get(x.id);if(!e||!e.dates.includes(x.day)||key!==k(x.id,x.day))continue;m.entries[key]={...makeEntry(e,x.day),start:x.start||'',end:x.end||'',snapshot:x.snapshot||signature(e,x.day),partialConfirmed:false};}m.settings.buffer=[0,5,10,15,20,30].includes(raw?.buffer)?raw.buffer:10;m.settings.speed=[50,70,90].includes(raw?.speed)?raw.speed:70;m.day=raw?.day||initialDay;/* Old hand-entered legs are deliberately not trusted: source signature format changed. */importConfirm(hydrate(m));}catch{toast('旧版の保存を読み取れませんでした。元データは変更していません。');}}
function eventRow(id,day){const e=EV.get(id);if(!e||!e.dates.includes(day)||!knownTime(e,day))return null;const x=model.entries[k(id,day)];if(['check','soldout'].includes(e.status)&&x?.reviewed!==signature(e,day))return null;if(x){const r=dayRows(day).find(r=>r.key===k(id,day));if(r.invalid||r.changed||r.needsReview||r.needsPartialReview)return null;return calendarRows({...itinerary(day),ordered:[r],legs:[]})[0];}const [s,t]=slot(e,day).map(min);return {uid:k(id,day),day,start:s,end:t,title:e.title,location:venueLocation(VEN.get(e.venue)),description:'参加予定。予約ではありません。主催者の変更は自動同期されません。',url:ROOT+'?event='+encodeURIComponent(id)+'&on='+day+'&date=any'};}
function googleEvent(id,day){const r=eventRow(id,day);if(!r){toast('時刻または開催条件の確認が必要です。');return;}const u=new URL('https://calendar.google.com/calendar/render');u.search=new URLSearchParams({action:'TEMPLATE',text:r.title,dates:stamp(r.day,r.start)+'/'+stamp(r.day,r.end),details:r.description+'\n'+r.url,location:r.location,ctz:'Asia/Tokyo'});window.open(u.href,'_blank','noopener,noreferrer');}
function printPlan(){const days=exportDays(),root=$('#print-root');closeModal();root.innerHTML=days.map(day=>{const p=itinerary(day);return `<section class="print-day"><p>RAMEN TECH 2026 非公式回遊ガイド｜Garraway F${demo?' ／ 操作例':''}</p><h1>${dayName(day)} マイ予定</h1><p>${p.rows.length}予定 ／ 移動${p.travel}分${p.unknown?'＋未確認':''} ／ 候補や検索結果はこの印刷に含みません。</p>${p.issues.length?'<div class="print-note">要確認：'+[...new Set(p.issues.map(x=>esc(x.text)))].join(' ／ ')+'</div>':''}<div class="print-map">${mapHTML('print-map-'+day,planItems(p),'会場の位置と訪問順','破線は実際の歩行経路ではありません。')}</div>${planTable(p,true)}<p class="print-disclaimer">この予定は参加予約ではありません。移動は目安で、実際の経路・到着を保証しません。申込状況は自己申告です。主催者の変更は自動反映されません。掲載情報取得時点：${esc(D.meta.fetchedAt)}。</p></section>`;}).join('');root.style.cssText='display:block;position:absolute;left:-2000px;width:730px;';root.setAttribute('aria-hidden','false');for(const day of days){const node=document.getElementById('print-map-'+day);node.querySelector('.map-heading').remove();node.querySelector('.map-status').style.display='none';node.querySelector('.map-legend').remove();node.querySelector('.map-route-list')?.remove();mountMap('print-map-'+day,planItems(itinerary(day)));}root.style.cssText='';requestAnimationFrame(()=>window.print());}
function startDemo(next='plan'){closeModal();if(!demo){userModel=model;demo=true;const loaded=load(DEMO_KEY);if(Object.keys(loaded.entries).length)model=loaded;else{model=newModel();model.day='2026-10-08';const examples=[['coffee-8','10:00','11:00'],['slot-32c206f2-e7b1-409b-bf1f-f7cb8fda1012','',''],['event-cross-border-open-innovation-day','',''],['connect-8','18:30','19:30']];for(const [id,start,end] of examples){const e=EV.get(id);if(e&&e.dates.includes(model.day)){const x=makeEntry(e,model.day);x.start=start;x.end=end;x.partialConfirmed=isFlexible(e);model.entries[k(id,model.day)]=x;}}model.candidates=['coffee-8','event-cross-border-open-innovation-day'].filter(id=>EV.has(id));}}persist();counts();scrollStates[next]=0;displayScreen(next);toast('実在の企画を使った仮の参加計画です。予約・申込は行っていません。');}
function exitDemo(){if(!demo)return;closeModal();demo=false;model=userModel;planFocus='';undo=null;counts();displayScreen('plan');toast('操作例を終了しました。あなたの確認用予定に戻りました。');}
function resetTime(key){const x=model.entries[key];if(!x)return;rememberUndo();x.start='';x.end='';x.partialConfirmed=false;closeModal();changed();toast('自分の参加時間を、公表されている開催時間に戻しました。',true);}
function safeFocusAfter(d){requestAnimationFrame(()=>{let node;if(d.candidate)node=$$('[data-candidate]').find(el=>el.dataset.candidate===d.candidate);else if(d.add)node=$$('[data-add]').find(el=>el.dataset.add===d.add&&el.dataset.day===d.day);if(node)node.focus({preventScroll:true});});}
document.addEventListener('click',ev=>{const b=ev.target.closest('button,a');if(!b)return;const d=b.dataset;
 if(d.screen){ev.preventDefault();closeModal();displayScreen(d.screen);return;}
 if(d.candidate){toggleCandidate(d.candidate);safeFocusAfter(d);return;}if(d.add){add(d.add,d.day);safeFocusAfter(d);return;}if(d.detail){detail(d.detail,d.day);return;}
 if(d.remove){remove(d.remove);return;}if(d.registration){registration(d.registration);return;}if(d.editTime){editTime(d.editTime);return;}if(d.resetTime){resetTime(d.resetTime);return;}if(d.editLeg){editLeg(d.editLeg);return;}if(d.review){review(d.review);return;}if(d.focusPlan){focusPlan(d.focusPlan);return;}
 if(d.showStop){const m=mapViews.get('plan-map');if(m?.items.some(x=>x.key===d.showStop&&geo(x.venue))){m.selectKey(d.showStop);m.root.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}else{const x=model.entries[d.showStop];if(x)detail(x.id,x.day);toast('この会場は位置未確認、または時刻未確定のため訪問順の対象外です。');}return;}
 if(d.planDay){model.day=d.planDay;planFocus='';persist();renderCurrent();return;}if(d.planView){model.view=d.planView;persist();renderPlan();return;}if(d.date){filters.day=d.date;closeModal();screen='explore';displayScreen('explore',{scroll:false});filterChanged();return;}
 if(d.quick){const [key,value]=d.quick.split(':');filters[key]=filters[key]===value?baseFilters[key]:value;filterChanged();return;}
 if(d.clearFilter){const key=d.clearFilter;if(Object.hasOwn(baseFilters,key))filters[key]=baseFilters[key];filterChanged();return;}
 if(d.mapMode){mapViews.get(d.map)?.setMode(d.mapMode);return;}if(d.mapZoom){mapViews.get(d.map)?.changeZoom(+d.mapZoom);return;}if(d.mapFit){mapViews.get(d.mapFit)?.fit();return;}if(d.mapGroup!==undefined){mapViews.get(d.map)?.selectGroup(+d.mapGroup);return;}if(d.mapItem){mapViews.get(d.map)?.selectKey(d.mapItem);return;}
 if(d.searchVenue){filters.venue=d.searchVenue;filters.q='';filters.candidates=false;filters.limit=18;if(!occurrences().length)filters.day='any';scrollStates.explore=0;displayScreen('explore');updateURL();return;}
 if(d.searchGap){searchGap(d.searchGap);return;}if(d.gap){suggestGap(d.gap);return;}if(d.addSuggestion!==undefined){const p=pending,sel=p?.picks?.[+d.addSuggestion];if(sel){closeModal();add(sel.e.id,p.day,{times:[time(sel.start),time(sel.end)]});}return;}
 if(d.googleEvent){googleEvent(d.googleEvent,d.day);return;}if(d.icsEvent){const r=eventRow(d.icsEvent,d.day);if(!r){toast('時刻や開催条件の確認が必要です。');return;}download('ramen-event-'+d.day+'.ics',createICS([r]),'text/calendar;charset=utf-8');toast(dayName(d.day)+'の1枠を保存しました。');return;}
 const a=d.action;if(!a)return;
 if(a==='dismiss-toast')$('#toast').classList.remove('visible');else if(a==='help')openHelp();else if(a==='close-modal')closeModal();else if(a==='filters')openFilters();else if(a==='settings')openSettings();else if(a==='demo'||a==='demo-today')startDemo(a==='demo-today'?'today':'plan');else if(a==='exit-demo')exitDemo();
 else if(a==='clear-query'){filters.q='';filterChanged();$('#query').focus();}else if(a==='candidate-filter'){filters.candidates=!filters.candidates;filterChanged();}
 else if(a==='reset-filters'||a==='reset-filters-modal'){filters={...baseFilters,day:filters.day};closeModal();displayScreen('explore',{scroll:false});filterChanged();}
 else if(a==='more'){filters.limit+=18;renderExplore();}else if(a==='layout'){filters.layout=filters.layout==='cards'?'list':'cards';filterChanged();}
 else if(a==='related-dates'){openModal('dates','参加する日程を選ぶ',`<p class="modal-intro">本会期以外の関連日程も確認できます。開催日と利用条件は各イベントの主催者案内が基準です。</p><div class="detail-actions"><button class="button secondary" data-date="main">本会期 10/7–11</button><button class="button secondary" data-date="pre">9/30–10/6</button><button class="button secondary" data-date="after">10/12–14</button></div><div class="field-grid">${allDays.map(day=>`<button class="button secondary" data-date="${day}" style="margin:5px 0">${dayName(day)}</button>`).join('')}</div>`);}
 else if(a==='gf-search'){filters={...baseFilters,day:'any',venue:'garraway'};scrollStates.explore=0;displayScreen('explore');updateURL();}
 else if(a==='undo'){if(undo&&undo.demo===demo){model=undo.model;if(!demo)userModel=model;undo=null;changed();toast('直前の変更を元に戻しました。');}}
 else if(a==='replace-related'||a==='keep-related'){const p=pending;closeModal();add(p.id,p.day,{force:true,removeKeys:a==='replace-related'?p.keys:[],times:p.times});}
 else if(a==='reset-leg'){const key=pending?.key;if(key){rememberUndo();delete model.legs[key];closeModal();changed();toast('徒歩の目安による自動計算に戻しました。',true);}}
 else if(a==='export')openExport();else if(a==='export-ics')exportICS();else if(a==='copy-plan')copyPlan();else if(a==='print-plan')printPlan();else if(a==='backup')backup();else if(a==='import')importFile();else if(a==='import-legacy')importLegacy();else if(a==='download-text'){const text=$('#copy-text')?.value||shareText(exportDays());download('ramen-plan.txt',text,'text/plain;charset=utf-8');toast('予定のテキストファイルを保存しました。');}
 else if(a==='go-plan'){$('#toast').classList.remove('visible');closeModal();displayScreen('plan');$('#plan-content').scrollIntoView({block:'start'});}
 else if(a==='merge-import'){const incoming=pending?.model;if(!incoming)return;rememberUndo();model.candidates=[...new Set([...model.candidates,...incoming.candidates])];model.entries={...incoming.entries,...model.entries};/* Current settings/legs have priority when merging. */model.legs={...incoming.legs,...model.legs};closeModal();changed();displayScreen('plan');toast('既存の予定を優先して、読み込み内容を追加しました。',true);}
 else if(a==='replace-import-confirm'){openModal('import-confirm','今の確認用予定を置き換えますか',`<p class="modal-intro">現在の${Object.keys(model.entries).length}件の予定・候補・移動設定を、選んだファイルの内容で置き換えます。必要な場合は先にバックアップしてください。本番サイトの保存データは変更しません。</p><div class="merge-choice"><button class="button secondary" data-action="backup">今の内容をバックアップ</button><button class="button danger" data-action="replace-import">読み込み内容で置き換える</button><button class="button secondary" data-action="close-modal">中止する</button></div>`);}
 else if(a==='replace-import'){if(!pending?.model)return;rememberUndo();model=hydrate(pending.model);if(!demo)userModel=model;closeModal();changed();displayScreen('plan');toast('選んだファイルの内容を読み込みました。',true);}
});
let queryTimer;
$('#query').addEventListener('input',e=>{if(e.isComposing)return;clearTimeout(queryTimer);queryTimer=setTimeout(()=>{filters.q=e.target.value.slice(0,160);filterChanged();},180);});
$('#query').addEventListener('compositionend',e=>{clearTimeout(queryTimer);filters.q=e.target.value.slice(0,160);filterChanged();});
document.addEventListener('change',async e=>{const target=e.target;
 if(target.id==='sort'){filters.sort=target.value;filterChanged();}else if(target.id==='detail-date')detail(target.dataset.id,target.value);else if(target.id==='export-scope'){exportScope=target.value;updateExportSummary();$('#export-error').hidden=true;}else if(target.id==='map-scope'){mapScope=target.value;renderAllMap();}else if(target.id==='map-area'){mapArea=target.value;renderAllMap();}else if(target.id==='today-test-time'){if(min(target.value)!==null){todayTestTime=target.value;renderToday();}}else if(target.id==='leg-mode'){const l=findLeg(pending?.key);$('#leg-minutes').value='';const a=$('#leg-form a');if(l&&a)a.href=directions(l.from.venue,l.to.venue,target.value);}
 else if(target.id==='import-file'){const file=target.files?.[0];if(!file)return;if(file.size>2*1024*1024){formError('2MB以下の予定ファイルを選んでください。');return;}try{const raw=JSON.parse(await file.text()),m=hydrate(raw);importConfirm(m,raw.sample===true);}catch{formError('このガイドの有効な .json ファイルを読み込めませんでした。現在の保存は変更していません。');}}
});
document.addEventListener('submit',ev=>{const form=ev.target;if(!form.matches('#filter-form,#leg-form,#visit-form,#registration-form,#review-form,#settings-form'))return;ev.preventDefault();const data=new FormData(form);
 if(form.id==='filter-form'){const from=data.get('from')||'',until=data.get('until')||'';if(from&&until&&min(from)>=min(until)){formError('終了の上限は、開始の下限より後にしてください。');return;}for(const name of ['venue','category','area','period','fee','kind','from','until'])filters[name]=String(data.get(name)||'');filters.known=data.has('known');filters.candidates=data.has('candidates');closeModal();displayScreen('explore',{scroll:false});filterChanged();}
 else if(form.id==='leg-form'){const l=findLeg(form.dataset.key);if(!l)return;const mode=String(data.get('mode')),str=String(data.get('minutes')||'').trim(),value=str===''?null:Number(str);if(str!==''&&(!Number.isInteger(value)||value<0||value>720)){formError('所要時間は0〜720分の整数で入力してください。');return;}if(mode!=='walking'&&value===null){formError('公共交通・車・タクシーは、地図で確認した所要時間を入力してください。');return;}rememberUndo();model.legs[l.key]={mode,minutes:value,signature:l.signature};closeModal();changed();toast('移動方法と所要時間を反映しました。',true);}
 else if(form.id==='visit-form'){const key=form.dataset.key,x=model.entries[key],e=EV.get(x?.id);if(!x||!e)return;const a=String(data.get('start')),b=String(data.get('end')),s=min(a),t=min(b),[ps,pe]=slot(e,x.day).map(min);if(s===null||t===null||t<=s){formError('参加終了は参加開始より後にしてください。');return;}if(s<ps||t>pe){formError('主催者が公表している開催時間の範囲内で設定してください。');return;}const partial=s!==ps||t!==pe;if(partial&&!isFlexible(e)&&!data.has('partial')){formError('途中入退場の可否を主催者に確認し、確認欄にチェックしてください。');return;}rememberUndo();x.start=partial?a:'';x.end=partial?b:'';x.partialConfirmed=partial&&(isFlexible(e)||data.has('partial'));closeModal();changed();toast('自分の参加時間を変更しました。開催時間そのものは変更していません。',true);}
 else if(form.id==='registration-form'){const x=model.entries[form.dataset.key];if(!x)return;x.registration=String(data.get('registration'));closeModal();changed();toast('申込状況を自分用メモとして記録しました。');}
 else if(form.id==='review-form'){if(!data.has('read'))return;const x=model.entries[form.dataset.key],e=EV.get(x?.id);if(!e)return;x.snapshot=signature(e,x.day);x.reviewed=signature(e,x.day);closeModal();changed();toast('開催条件の確認を記録しました。未確定の時刻は引き続き確認が必要です。');}
 else if(form.id==='settings-form'){model.settings.buffer=+data.get('buffer');model.settings.speed=+data.get('speed');closeModal();changed();toast('予備時間と徒歩の計算条件を反映しました。');}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('cancel',()=>{modalType='';});
